#!/usr/bin/env bash
set -euo pipefail
source "$(dirname "${BASH_SOURCE[0]}")/../common.sh"
mkdir -p build
workspace="$(mktemp -d "$root/build/standard-form-fields-smoke-XXXXXX")"
openapi_kt_build_cli "$workspace/openapi-kt"
for style in data_class plain_class; do
  for checked in off on; do
    project="$workspace/$style-$checked"
    mkdir -p "$project/src/main/kotlin/org/example/contracts"
    cp samples/kotlin-http-smoke/{build.gradle.kts,settings.gradle.kts} "$project/"
    cp samples/kotlin-http-smoke/src/main/kotlin/org/example/contracts/StandardFormFieldsMediaContracts.kt "$project/src/main/kotlin/org/example/contracts/"
    flags=(--model-style "$style")
    if [[ "$checked" == on ]]; then flags+=(--validation); fi
    python3 - "$project" "$checked" <<'PYINPUT'
from pathlib import Path
import json,sys
p=Path(sys.argv[1]);checked=sys.argv[2]=='on'
d=json.loads(Path('tests/fixtures/http/standard-form-fields.json').read_text())
if checked:
 for path in d['paths'].values():
  for op in path.values():
   for media in op['requestBody']['content'].values():
    text=media['schema'].get('properties',{}).get('uuidValue')
    if text is not None:text['pattern']='^123e4567-'
(p/'input.json').write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
fields={'p'+str(i):{'type':'string','format':['uuid','date','date-time'][i%3]} for i in range(240)}
wide={'openapi':'3.1.0','paths':{'/wide':{'post':{'operationId':'wide','requestBody':{'required':True,'content':{'application/x-www-form-urlencoded':{'schema':{'type':'object','properties':fields,'required':list(fields)}}}},'responses':{'204':{}}}}}}
(p/'wide.json').write_text(json.dumps(wide)+'\n')
consumer=p/'src/main/kotlin/org/example/contracts/StandardFormFieldsMediaContracts.kt'
(p/'src/main/kotlin/org/example/contracts/OptimizedStandardFormFieldsMediaContracts.kt').write_text(consumer.read_text().replace('org.example.standardform','org.example.standardformoptimized').replace('StandardFormFields','OptimizedStandardFormFields').replace('standardFormFields','optimizedStandardFormFields'))
